        build_scenario_tags(source2_reporting_business_line,source2_reporting_module, source2_reporting_object, null, source2_algo_tag, null) ) 
        , array(
                'dpm module Global Search business line Search',
                'DA_Daily Discover', 'DA_You May Also Like', 'DA_Cart_Unify'
                'DA_Buy Again (Me Page)','DA_Cart Recommendation','DA_odp_ymal-order_detail',
                'DA_Order Successful Recommendation','DA_mpp_ymal-order_list','DA_Me YMAL','DA_Shop YMAL','DA_Shop_Unify',
                'dpm_HP_DD + dpm_Global Search', 'dpm_PDP_YMAL + dpm_Global Search', 'dpm_PP_YMAL + dpm_Global Search'
            )
    ) AS union_algo_tags
    ,local_date
    ,SUM(net_order_cnt) AS net_order_cnt
