    --     OR (source1_algo_tag != '' AND EXISTS(SPLIT(source1_algo_tag, ','), x -> x IN ('DA_Daily Discover', 'DA_You May Also Like', 'DA_Cart_Unify'
    --     'DA_Buy Again (Me Page)','DA_Cart Recommendation','DA_odp_ymal-order_detail',
