    --     OR (source2_reporting_module = 'Global Search' AND source2_reporting_business_line = 'Search')
    --     OR (source2_algo_tag != '' AND EXISTS(SPLIT(source2_algo_tag, ','), x -> x IN ('DA_Daily Discover', 'DA_You May Also Like', 'DA_Cart_Unify'
    --     'DA_Buy Again (Me Page)','DA_Cart Recommendation','DA_odp_ymal-order_detail',
    --     'DA_Order Successful Recommendation','DA_mpp_ymal-order_list','DA_Me YMAL','DA_Shop YMAL','DA_Shop_Unify')))
    -- )
GROUP BY 
    1,2,3,4,5
UNION ALL
SELECT
    user_id
    ,COALESCE(CAST(is_ads AS STRING), 'false') AS is_ads
    ,COALESCE(platform, 'NULL') AS platform
    ,array('__ALL__') AS union_algo_tags
    ,local_date
    ,SUM(net_order_cnt) AS net_order_cnt
    ,SUM(nmv) AS nmv
FROM
    srdi_mart.dwd_sr_data_warehouse_platform_nmv
WHERE
    grass_region = ${grass_region}
    AND local_date BETWEEN DATE_SUB(${local_date}, 7) AND ${local_date}
    AND user_id > 0
GROUP BY 
    1,2,3,4,5;

