CREATE TEMPORARY VIEW dwm_platform_nmv_explode_${grass_region_without_quote} AS
SELECT
    user_id
    ,is_ads
    ,platform
    ,scenario_tag
    ,local_date
    ,SUM(net_order_cnt) AS net_order_cnt
    ,SUM(nmv) AS nmv
FROM
    dwm_platform_nmv_${grass_region_without_quote}
LATERAL VIEW EXPLODE(union_algo_tags) AS scenario_tag
GROUP BY
    1,2,3,4,5;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dwm_platform_nmv_grouping_sets_${grass_region_without_quote} AS
SELECT
    user_id
    ,IF(GROUPING(is_ads) = 1, '__ALL__', is_ads) AS is_ads
    ,IF(GROUPING(platform) = 1, '__ALL__', platform) AS platform
    ,scenario_tag
    ,local_date
    ,SUM(net_order_cnt) AS net_order_cnt
    ,SUM(nmv) AS nmv
FROM
    dwm_platform_nmv_explode_${grass_region_without_quote}
GROUP BY
    user_id
    ,local_date
    ,scenario_tag
    ,CUBE(is_ads,platform);

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_platform_exp_${grass_region_without_quote} AS
SELECT
    scenario_tag
    ,platform
    ,is_ads
    ,exp_group_id
    ,a.local_date AS local_date
    ,SUM(nmv) AS nmv
    ,SUM(net_order_cnt) AS net_order_cnt
    ,SUM(IF(net_order_cnt > 0, 1, NULL)) AS net_order_uu
FROM
    dwm_platform_nmv_grouping_sets_${grass_region_without_quote} a
JOIN
    user_exp_mapping_7d_${grass_region_without_quote} b
ON
    a.user_id = b.user_id
    AND a.local_date = b.local_date
GROUP BY
    1,2,3,4,5;

--sql_divide_splitter--

